// logger, usage: log(this, "");
const log = global.get('logger');

// 1.  Settings
// A day only counts when the heat pump has actually been used on that day.
const MIN_RUN_POWER_W = 50;      // power above this value counts as 'running'
const MIN_DAY_ENERGY_KWH = 0.5;  // a day with less energy counts as 'not used'
const MIN_DAY_COVERAGE = 0.9;    // fraction of the day the sensors must have valid data

const ENTITY = {
    outside: "sensor.sparrow_p60_heat_pump_outside_temperature",
    water: "sensor.sparrow_p60_heat_pump_water_target_temperature",
    power: "sensor.sparrow_p60_heat_pump",
    cop: "sensor.heatpump_cop_not_below_0",
};

// 2.  Input
// msg.history:    state history per entity_id (exact, only as far back as the recorder keeps it)
// msg.statistics: hourly long-term statistics per entity_id (kept forever, mean/min/max per hour)
const history = msg.history || {};
const statistics = msg.statistics || {};

const DAY_MS = 86_400_000;
const HOUR_MS = 3_600_000;
const now = Date.now();

// Local midnight of the day after timestamp t
const nextDayStart = (t) => {
    const d = new Date(t);
    return new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1).getTime();
};
const dayKey = (t) => {
    const d = new Date(t);
    const pad = (v) => String(v).padStart(2, "0");
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};
const toMs = (t) => typeof t === "number" ? (t < 1e12 ? t * 1000 : t) : new Date(t).getTime();
const round = (v, digits) => (v === null || v === undefined || !isFinite(v)) ? null : Number(v.toFixed(digits));
const today = dayKey(now);

// 3a. State history: exact time-weighted averages
// Convert HA states into time segments [start, end) with a numeric value.
// A state is valid until the next state change. Unknown / unavailable states become gaps.
function toSegments(states) {
    const points = (states || [])
        .map(s => ({
            t: toMs(s.last_changed ?? s.lc ?? s.lu ?? s.last_updated), // full or minimal response
            v: parseFloat(s.state ?? s.s),
        }))
        .filter(p => isFinite(p.t))
        .sort((a, b) => a.t - b.t);

    const segments = [];
    points.forEach((p, i) => {
        const end = (i < points.length - 1) ? points[i + 1].t : now;
        if (isFinite(p.v) && end > p.t) segments.push({ start: p.t, end: end, v: p.v });
    });
    return segments;
}

// Split segments on local midnight and accumulate time-weighted sums per day.
// `include` decides which values take part in the average (e.g. skip COP = 0).
function historyPerDay(segments, include = () => true) {
    const days = {};
    segments.forEach(seg => {
        let start = seg.start;
        while (start < seg.end) {
            const end = Math.min(seg.end, nextDayStart(start));
            const day = days[dayKey(start)] ??= { sum: 0, ms: 0, covered_ms: 0, above_ms: 0 };
            const ms = end - start;
            day.covered_ms += ms;
            if (include(seg.v)) {
                day.sum += seg.v * ms;
                day.ms += ms;
            }
            if (seg.v > MIN_RUN_POWER_W) day.above_ms += ms;
            start = end;
        }
    });
    return days;
}

// 3b. Long-term statistics: hourly means
// The COP mean of an hour includes the 0 values while the heat pump is off. Hours with
// min > 0 ran the full hour and give a clean COP; only when a day has none of those,
// hours with mean > 0 are used (slightly too low COP).
function statisticsPerDay(rows) {
    const days = {};
    (rows || []).forEach(r => {
        const mean = parseFloat(r.mean);
        if (!isFinite(mean)) return;
        const day = days[dayKey(toMs(r.start))] ??= { hours: [] };
        day.hours.push({ mean: mean, min: parseFloat(r.min), max: parseFloat(r.max) });
    });
    return days;
}
const meanOf = (values) => values.length ? values.reduce((s, v) => s + v, 0) / values.length : null;

// 3c. Build one row per day
const H = {
    outside: historyPerDay(toSegments(history[ENTITY.outside])),
    water: historyPerDay(toSegments(history[ENTITY.water])),
    power: historyPerDay(toSegments(history[ENTITY.power])),
    cop: historyPerDay(toSegments(history[ENTITY.cop]), v => v > 0), // do not average the 0 values
};
const S = {
    outside: statisticsPerDay(statistics[ENTITY.outside]),
    water: statisticsPerDay(statistics[ENTITY.water]),
    power: statisticsPerDay(statistics[ENTITY.power]),
    cop: statisticsPerDay(statistics[ENTITY.cop]),
};

// Exact row from the state history, or undefined when the day is not fully covered
function rowFromHistory(key) {
    const p = H.power[key], o = H.outside[key], w = H.water[key], c = H.cop[key];
    if (!p || !o || p.covered_ms < MIN_DAY_COVERAGE * DAY_MS || o.covered_ms < MIN_DAY_COVERAGE * DAY_MS) return undefined;
    const powerAvg = p.sum / p.ms; // hours without data are assumed to match the measured hours
    return {
        date: key,
        source: "history",
        used: powerAvg * 24 / 1000 >= MIN_DAY_ENERGY_KWH && p.above_ms > 0,
        outside_temp_avg: round(o.sum / o.ms, 1),
        water_target_temp_avg: w && w.ms > 0 ? round(w.sum / w.ms, 1) : null,
        power_avg: round(powerAvg, 0),
        energy: round(powerAvg * 24 / 1000, 2),
        running_hours: round(p.above_ms / HOUR_MS, 1),
        cop_avg: c && c.ms > 0 ? round(c.sum / c.ms, 2) : null,
    };
}

// Row from the hourly statistics, or undefined when the day is not fully covered
function rowFromStatistics(key) {
    const p = S.power[key], o = S.outside[key], w = S.water[key], c = S.cop[key];
    if (!p || !o || p.hours.length < MIN_DAY_COVERAGE * 24 || o.hours.length < MIN_DAY_COVERAGE * 24) return undefined;
    const powerAvg = meanOf(p.hours.map(h => h.mean));
    const copHours = c ? c.hours.filter(h => h.min > 0) : [];
    const copValues = (copHours.length ? copHours : (c ? c.hours.filter(h => h.mean > 0) : [])).map(h => h.mean);
    return {
        date: key,
        source: "statistics",
        used: powerAvg * 24 / 1000 >= MIN_DAY_ENERGY_KWH && p.hours.some(h => h.max > MIN_RUN_POWER_W),
        outside_temp_avg: round(meanOf(o.hours.map(h => h.mean)), 1),
        water_target_temp_avg: w ? round(meanOf(w.hours.map(h => h.mean)), 1) : null,
        power_avg: round(powerAvg, 0),
        energy: round(powerAvg * 24 / 1000, 2),
        running_hours: p.hours.filter(h => h.mean > MIN_RUN_POWER_W).length, // approximation
        cop_avg: round(meanOf(copValues), 2),
    };
}

// The exact state history wins; statistics fill in the days the recorder has purged
const keys = new Set([...Object.keys(H.power), ...Object.keys(S.power)]);
keys.delete(today); // incomplete day
const rows = [];
let skipped = 0;
[...keys].sort().forEach(key => {
    const row = rowFromHistory(key) ?? rowFromStatistics(key);
    if (row && row.used) {
        delete row.used;
        rows.push(row);
    } else {
        skipped++; // not used or not enough data
    }
});

if (rows.length === 0) {
    log(this, "No days found on which the heat pump has been used", "warn");
    node.status({ fill: "red", shape: "ring", text: "No usable days" });
    return null;
}

// 4.  Relation to the outside temperature
// Least squares fit y = slope * outside + intercept
function fit(key) {
    const pts = rows.filter(r => r[key] !== null && r.outside_temp_avg !== null);
    const n = pts.length;
    if (n < 2) return null;
    const mx = pts.reduce((s, r) => s + r.outside_temp_avg, 0) / n;
    const my = pts.reduce((s, r) => s + r[key], 0) / n;
    const sxx = pts.reduce((s, r) => s + (r.outside_temp_avg - mx) ** 2, 0);
    if (sxx === 0) return null;
    const sxy = pts.reduce((s, r) => s + (r.outside_temp_avg - mx) * (r[key] - my), 0);
    const slope = sxy / sxx;
    return { slope: round(slope, 3), intercept: round(my - slope * mx, 2), days: n };
}

const average = (list, key, digits = 2) => round(meanOf(list.map(r => r[key]).filter(v => v !== null)), digits);

// Averages per whole °C outside temperature
const bins = {};
rows.forEach(r => (bins[Math.round(r.outside_temp_avg)] ??= []).push(r));
const curve = Object.keys(bins).map(Number).sort((a, b) => a - b).map(t => ({
    outside_temp: t,
    days: bins[t].length,
    water_target_temp: average(bins[t], "water_target_temp_avg", 1),
    power: average(bins[t], "power_avg", 0),
    energy: average(bins[t], "energy", 2),
    cop: average(bins[t], "cop_avg", 2),
}));

// 5.  Output
const summary = {
    updated: new Date(now).toISOString(),
    first_day: rows[0].date,
    last_day: rows[rows.length - 1].date,
    days_used: rows.length,
    days_from_history: rows.filter(r => r.source === "history").length,
    days_from_statistics: rows.filter(r => r.source === "statistics").length,
    days_skipped: skipped,
    averages: {
        outside_temp_avg: average(rows, "outside_temp_avg", 1),
        water_target_temp_avg: average(rows, "water_target_temp_avg", 1),
        power_avg: average(rows, "power_avg", 0),
        energy: average(rows, "energy", 2),
        cop_avg: average(rows, "cop_avg", 2),
    },
    // per °C outside temperature: value = slope * outside_temp + intercept
    fit: {
        water_target_temp: fit("water_target_temp_avg"),
        power: fit("power_avg"),
        cop: fit("cop_avg"),
    },
    curve: curve,
};

// Full day list stays in Node-RED, Home Assistant gets the (small) summary
global.set("heat_pump_history", { ...summary, days: rows });
msg.heat_pump_history = summary;
delete msg.history; // raw data is large, do not pass it on
delete msg.statistics;

log(this, `${rows.length} days used (${summary.first_day} .. ${summary.last_day}), ${skipped} skipped`);
node.status({ fill: "green", shape: "dot", text: `${rows.length} days | COP ${summary.averages.cop_avg ?? "-"}` });

return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

return msg;

// logger, usage: log(this, "");
const log = global.get('logger');

// 1.  Settings
// Below this water temperature the heating curve is replaced by the simple day schedule:
// heat at this temperature from the start time until the inside temperature is reached.
const SIMPLE_WATER_TEMP = 24; // °C
const MAX_FORECAST_AGE_H = 3;  // older cached forecasts are not used

// 2.  Input
const ff = msg.feedforward || {};
const outside = parseFloat(ff.outside_temp);
const outsideAvg = parseFloat(ff.outside_temp_avg);
const inside = parseFloat(ff.inside_temp);
const minWater = parseFloat(ff.min_water_temp);
const maxWater = parseFloat(ff.max_water_temp);
const simpleFrom = parseFloat(ff.simple_outside_temp);
const simpleStop = parseFloat(ff.simple_stop_inside_temp);
const leadTime = parseFloat(ff.forecast_lead_time) || 0;       // h ahead
const window = parseFloat(ff.forecast_window) || 0;            // h averaged, from the lead time
const weight = parseFloat(ff.forecast_weight);                 // % forecast, rest current temperature
const simpleHours = parseFloat(ff.simple_forecast_hours) || 24; // h ahead, average for the simple schedule
const correctBias = ff.forecast_bias_correction === "on";       // shift the forecast to the measured temperature
const history = global.get("heat_pump_history");
const forecast = flow.get("weather_forecast"); // { fetched, list: [{ t, temp }] }

const HOUR_MS = 3_600_000;
const now = Date.now();

if (!isFinite(outside)) {
    log(this, "Outside temperature unavailable", "warn");
    node.status({ fill: "red", shape: "ring", text: "No outside temperature" });
    return null;
}

const round = (v, digits) => (v === null || v === undefined || !isFinite(v)) ? null : Number(v.toFixed(digits));

// 3.  Outside temperature: current or forecast
// Forecast temperature at time t, linear between the hourly forecast points
function forecastAt(t) {
    const list = forecast.list;
    if (t <= list[0].t) return list[0].temp;
    for (let i = 1; i < list.length; i++) {
        if (t <= list[i].t) {
            const a = list[i - 1], b = list[i];
            return a.temp + (b.temp - a.temp) * (t - a.t) / (b.t - a.t);
        }
    }
    return list[list.length - 1].temp;
}
// Average forecast temperature over [from, from + hours], sampled every 15 minutes
function forecastAverage(from, hours) {
    const steps = Math.max(1, Math.round(hours * 4));
    let sum = 0;
    for (let i = 0; i < steps; i++) sum += forecastAt(from + (i + 0.5) * hours * HOUR_MS / steps);
    return hours > 0 ? sum / steps : forecastAt(from);
}

let outsideSource = ff.outside_source || "Current";
let outsideUsed = outside;     // used for the heating curve
let outsideAvgUsed = outsideAvg; // used to activate the simple schedule
let forecastTemp = null;
let forecastBias = 0;
if (outsideSource === "Forecast") {
    const fresh = forecast && Array.isArray(forecast.list) && forecast.list.length > 0 &&
        now - forecast.fetched < MAX_FORECAST_AGE_H * HOUR_MS;
    if (fresh) {
        // The heat pump sensor often differs from the weather forecast (sun, defrost, location):
        // optionally shift the whole forecast by the difference measured right now
        if (correctBias) forecastBias = outside - forecastAt(now);
        forecastTemp = forecastAverage(now + leadTime * HOUR_MS, window) + forecastBias;
        const w = isFinite(weight) ? Math.min(Math.max(weight, 0), 100) / 100 : 1;
        outsideUsed = outside + w * (forecastTemp - outside);
        outsideAvgUsed = forecastAverage(now, simpleHours) + forecastBias;
    } else {
        log(this, "No recent weather forecast, using the current outside temperature", "warn");
        outsideSource = "Current (forecast unavailable)";
    }
}

const atOutside = (line) => line ? line.slope * outsideUsed + line.intercept : null;

// 4.  Select the heating curve: water = slope * outside + intercept
const manual = { slope: parseFloat(ff.manual_slope), intercept: parseFloat(ff.manual_intercept) };
const historyFit = history?.fit?.water_target_temp;

let source = ff.source;
let curve = manual;
if (source === "History") {
    if (historyFit) {
        curve = historyFit;
    } else {
        // History not calculated yet (e.g. just after a restart), fall back to the manual curve
        log(this, "No history curve available, using manual values", "warn");
        source = "Manual (history unavailable)";
    }
}

if (!isFinite(curve.slope) || !isFinite(curve.intercept)) {
    log(this, "Heating curve incomplete", "warn");
    node.status({ fill: "red", shape: "ring", text: "No heating curve" });
    return null;
}

// 5a. Curve: feedforward water temperature, limited to min / max
let mode = "Curve";
let heating = true;
let water = atOutside(curve);
if (isFinite(minWater)) water = Math.max(water, minWater);
if (isFinite(maxWater)) water = Math.min(water, maxWater);

// 5b. Simple day schedule, effective from the set average outside temperature
if (isFinite(outsideAvgUsed) && isFinite(simpleFrom) && outsideAvgUsed >= simpleFrom) {
    mode = "Simple";
    water = SIMPLE_WATER_TEMP;

    // The heating day starts at the start time, before that time the previous day still counts
    const [h, m] = String(ff.simple_start_time || "00:00").split(":").map(Number);
    const today = new Date(now);
    const start = new Date(today.getFullYear(), today.getMonth(), today.getDate(), h || 0, m || 0);
    if (now < start.getTime()) start.setDate(start.getDate() - 1);
    const heatingDay = start.toISOString();

    // Stop for the rest of the heating day once the inside temperature is reached
    if (flow.get("simple_stopped_day") !== heatingDay) {
        if (!isFinite(inside)) {
            log(this, "Inside temperature unavailable, keep heating", "warn");
        } else if (isFinite(simpleStop) && inside >= simpleStop) {
            log(this, `Inside temperature ${inside} °C reached, stop heating for today`);
            flow.set("simple_stopped_day", heatingDay);
        }
    }
    heating = flow.get("simple_stopped_day") !== heatingDay;
}

// 6.  Output
msg.feedforward = {
    ...ff,
    outside_temp: outside,
    outside_temp_avg: round(outsideAvg, 1),
    outside_source: outsideSource,
    forecast_temp: round(forecastTemp, 1),
    forecast_bias: round(forecastBias, 1),
    outside_temp_used: round(outsideUsed, 1),        // heating curve
    outside_temp_avg_used: round(outsideAvgUsed, 1), // simple schedule
    inside_temp: round(inside, 1),
    source: source,
    slope: curve.slope,
    intercept: curve.intercept,
    mode: mode,
    heating: heating, // false: heat pump off for the rest of the heating day
    water_temp: round(water, 1),
    // expected values from the history at this outside temperature, for information
    expected_power: round(atOutside(history?.fit?.power), 0),
    expected_cop: round(atOutside(history?.fit?.cop), 2),
};

global.set("heat_pump_feedforward", msg.feedforward);

const text = heating ? `${msg.feedforward.water_temp} °C` : "Off for today";
node.status({ fill: heating ? "green" : "grey", shape: "dot", text: `${text} @ ${round(outsideUsed, 1)} °C (${mode}, ${source}, ${outsideSource})` });
return msg;

// logger, usage: log(this, "");
const log = global.get('logger');

// Cache the hourly forecast as [{ t: ms, temp: °C }], read by the 'Feedforward' node
const response = msg.payload || {};
const list = (response["weather.forecast_home"] ?? Object.values(response)[0])?.forecast;

if (!Array.isArray(list) || list.length === 0) {
    log(this, "Weather forecast missing or empty", "warn");
    node.status({ fill: "red", shape: "ring", text: "No forecast" });
    return null;
}

const points = list
    .map(f => ({ t: new Date(f.datetime).getTime(), temp: parseFloat(f.temperature) }))
    .filter(p => isFinite(p.t) && isFinite(p.temp))
    .sort((a, b) => a.t - b.t);

flow.set("weather_forecast", { fetched: Date.now(), list: points });
node.status({ fill: "green", shape: "dot", text: `${points.length} hours, now ${points[0]?.temp} °C` });

// Recalculate the feedforward with the new forecast
return {};

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

return msg;
